# Demo and acceptance scope

## Terminology

- **First demo:** curated, pre-approved evidence reveal. This is not the final MVP.
- **Guarded-pilot MVP:** both secure display modes, private live recommendations, and a feature-flagged supervised path from an eligible live candidate to the public Stage.
- **Deferred enhancement:** automatic display placement, public live evidence before its gates, coaching, and generated report summaries.

## Supported environment

- Windows 11
- current stable Chrome and Edge
- wired Extend
- Duplicate with a separate private controller
- single-screen public Stage fallback

Manual Stage placement and a Stage-local fullscreen click are canonical. Browser Window Management is an optional enhancement.

## Secure display baseline

Both Extend and Duplicate use:

1. a clean public Stage browser profile on the presentation machine;
2. an already authenticated private controller on another device;
3. a short-lived, non-authorizing display join locator;
4. server-side display binding and an AudienceDisplaySession.

A co-resident Console in Extend mode is convenience-only and has no no-private-pixel claim.

## Preregistered evaluation

Before unblinding a frozen acceptance corpus, record:

- corpus hash and sampling frame;
- claim class and severity taxonomy;
- semantic acoustic endpoints;
- network and cache profile;
- formulas, thresholds, exclusions, and failure treatment;
- evaluator and rubric versions.

Development, provider bake-off, and acceptance data are disjoint by claim/paraphrase, source version, speaker recording, and deck instance.

Provisional live recommendation gates:

- semantic-audio-end to eligible Console render p95 <= 5 seconds;
- at most 3 results;
- eligible yield >= 60% for supportable, fetchable claims;
- direct top-3 usefulness >= 80% for answerable events;
- abstention >= 95% for intentionally unanswerable events;
- zero critical numeric, date, entity, and security escapes;
- at least 299 representative non-supportable cases with zero false-support escapes.

Live public evidence remains off until the signed evaluation record passes every applicable safety, usefulness, approval-load, lease, and recovery gate.

"""Shared contracts for structural extraction adapters."""

from abc import ABC, abstractmethod
from typing import NoReturn

from impromptu_ingestion.contracts import DeckManifest, InputKind, ValidatedInput


class StructuralExtractionError(RuntimeError):
    """A machine-identifiable parser failure safe to return from the worker."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


class RenderingUnsupportedError(RuntimeError):
    """Raised when callers cross the intentionally absent rendering boundary."""


class StructuralAdapter(ABC):
    """Extract structure without claiming visual render fidelity."""

    kind: InputKind

    def _require_kind(self, source: ValidatedInput) -> None:
        if source.kind is not self.kind:
            raise StructuralExtractionError(
                "adapter_kind_mismatch",
                f"{self.__class__.__name__} cannot extract {source.kind.value}",
            )

    @abstractmethod
    def extract(self, source: ValidatedInput) -> DeckManifest:
        """Extract a deterministic structural manifest."""

    @staticmethod
    def render_slides() -> NoReturn:
        raise RenderingUnsupportedError(
            "slide rendering is not configured; structural extraction cannot verify fidelity"
        )

"""python-pptx structural extraction without rendering or notes export."""

import hashlib
from collections.abc import Iterable, Sequence
from typing import Protocol, cast

from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
from pptx.shapes.base import BaseShape
from pptx.slide import Slide

from impromptu_ingestion.adapters.base import StructuralAdapter, StructuralExtractionError
from impromptu_ingestion.canonical import deck_id, slide_key
from impromptu_ingestion.contracts import (
    ChartElement,
    ChartSeries,
    DeckManifest,
    ExtractionWarning,
    ImageElement,
    InputKind,
    RenderBoundary,
    SlideManifest,
    StructuralElement,
    TableElement,
    TextElement,
    ValidatedInput,
)

_EMU_PER_POINT = 12_700


class _TableCell(Protocol):
    text: str


class _TableRow(Protocol):
    cells: Sequence[_TableCell]


class _Table(Protocol):
    rows: Sequence[_TableRow]


class _TableShape(Protocol):
    table: _Table


class _Series(Protocol):
    name: object | None
    values: Iterable[object | None]


class _Chart(Protocol):
    chart_type: object
    series: Iterable[_Series]


class _ChartShape(Protocol):
    chart: _Chart


class _Image(Protocol):
    blob: bytes
    content_type: str
    size: tuple[int, int]


class _ImageShape(Protocol):
    image: _Image


class _TextFrame(Protocol):
    text: str


class _TextShape(Protocol):
    text_frame: _TextFrame


def _points(value: int) -> float:
    return round(value / _EMU_PER_POINT, 4)


def _position(shape: BaseShape) -> tuple[float, float, float, float]:
    return (
        _points(shape.left),
        _points(shape.top),
        _points(shape.width),
        _points(shape.height),
    )


def _chart_series(shape: _ChartShape) -> tuple[ChartSeries, ...]:
    return tuple(
        ChartSeries(
            name=str(series.name or ""),
            values=tuple("" if value is None else str(value) for value in series.values),
        )
        for series in shape.chart.series
    )


def _extract_shape(shape: BaseShape) -> StructuralElement | None:
    element_id = f"shape:{shape.shape_id}"
    x, y, width, height = _position(shape)

    if shape.has_table:
        table_shape = cast(_TableShape, shape)
        rows = tuple(tuple(cell.text for cell in row.cells) for row in table_shape.table.rows)
        return TableElement(
            element_id=element_id,
            rows=rows,
            x=x,
            y=y,
            width=width,
            height=height,
        )

    if shape.has_chart:
        chart_shape = cast(_ChartShape, shape)
        return ChartElement(
            element_id=element_id,
            chart_type=str(chart_shape.chart.chart_type),
            series=_chart_series(chart_shape),
            x=x,
            y=y,
            width=width,
            height=height,
        )

    if shape.shape_type is MSO_SHAPE_TYPE.PICTURE:
        image = cast(_ImageShape, shape).image
        pixel_width, pixel_height = image.size
        return ImageElement(
            element_id=element_id,
            content_sha256=hashlib.sha256(image.blob).hexdigest(),
            media_type=image.content_type,
            pixel_width=pixel_width,
            pixel_height=pixel_height,
            x=x,
            y=y,
            width=width,
            height=height,
        )

    if shape.has_text_frame:
        text = cast(_TextShape, shape).text_frame.text.strip()
        if text:
            return TextElement(
                element_id=element_id,
                text=text,
                x=x,
                y=y,
                width=width,
                height=height,
            )
    return None


def _slide_manifest(
    slide: Slide,
    index: int,
    source_sha256: str,
    width_points: float,
    height_points: float,
) -> SlideManifest:
    elements: list[StructuralElement] = []
    warnings: list[ExtractionWarning] = []
    for shape in slide.shapes:
        element = _extract_shape(shape)
        if element is not None:
            elements.append(element)
        elif shape.shape_type not in {MSO_SHAPE_TYPE.PLACEHOLDER, MSO_SHAPE_TYPE.AUTO_SHAPE}:
            warnings.append(
                ExtractionWarning(
                    code="unsupported_shape",
                    message=f"shape {shape.shape_id} ({shape.shape_type}) was not extracted",
                )
            )

    source_id = f"slide:{slide.slide_id}"
    return SlideManifest(
        slide_key=slide_key(source_sha256, source_id),
        source_index=index,
        source_id=source_id,
        width_points=width_points,
        height_points=height_points,
        elements=tuple(elements),
        warnings=tuple(warnings),
    )


class PptxStructuralAdapter(StructuralAdapter):
    """Extract public slide structure; speaker notes are deliberately never read."""

    kind = InputKind.PPTX
    adapter_version = "python-pptx-structural-v1"

    def extract(self, source: ValidatedInput) -> DeckManifest:
        self._require_kind(source)
        try:
            presentation = Presentation(str(source.path))
            slide_width = cast(int, presentation.slide_width)
            slide_height = cast(int, presentation.slide_height)
            slides: Iterable[Slide] = presentation.slides
            manifests = tuple(
                _slide_manifest(
                    slide,
                    index,
                    source.source_sha256,
                    _points(slide_width),
                    _points(slide_height),
                )
                for index, slide in enumerate(slides, start=1)
            )
        except Exception as error:
            raise StructuralExtractionError(
                "invalid_document", "PPTX structure could not be parsed"
            ) from error

        if not manifests:
            raise StructuralExtractionError("empty_document", "PPTX contains no slides")
        return DeckManifest(
            deck_id=deck_id(source.source_sha256),
            source_sha256=source.source_sha256,
            source_kind=self.kind,
            adapter_version=self.adapter_version,
            slides=manifests,
            render_boundary=RenderBoundary.structural_only(),
        )

"""Defensive staging and validation at the local-file ingestion boundary."""

import hashlib
import os
import stat
from collections.abc import Generator
from contextlib import contextmanager
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from tempfile import TemporaryDirectory
from typing import BinaryIO
from zipfile import BadZipFile, ZipFile

from impromptu_ingestion.contracts import IngestionJob, InputKind, ValidatedInput

_CHUNK_SIZE = 1024 * 1024
_MAX_ARCHIVE_MEMBERS = 10_000
_MAX_ARCHIVE_UNCOMPRESSED_BYTES = 512 * 1024 * 1024
_PPTX_MAIN_CONTENT_TYPE = (
    b"application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"
)


class InputValidationError(ValueError):
    """A safe, machine-identifiable rejection at the input boundary."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


@dataclass(frozen=True)
class _FileIdentity:
    device: int
    inode: int
    size: int
    modified_ns: int


@dataclass(frozen=True)
class _StagedCopy:
    opened_identity: _FileIdentity
    final_identity: _FileIdentity
    size: int
    sha256: str


def _identity(metadata: os.stat_result) -> _FileIdentity:
    return _FileIdentity(
        device=metadata.st_dev,
        inode=metadata.st_ino,
        size=metadata.st_size,
        modified_ns=metadata.st_mtime_ns,
    )


def _kind_for_path(path: Path) -> InputKind:
    match path.suffix.lower():
        case ".pptx":
            return InputKind.PPTX
        case ".pdf":
            return InputKind.PDF
        case _:
            raise InputValidationError(
                "unsupported_extension", "only .pptx and .pdf inputs are supported"
            )


def _initial_identity(source: Path, max_input_bytes: int) -> _FileIdentity:
    try:
        metadata = source.lstat()
    except FileNotFoundError as error:
        raise InputValidationError("input_not_found", "input file does not exist") from error
    except OSError as error:
        raise InputValidationError(
            "input_unreadable", "input metadata could not be read"
        ) from error

    if stat.S_ISLNK(metadata.st_mode):
        raise InputValidationError("symlink_rejected", "symbolic-link inputs are not accepted")
    if not stat.S_ISREG(metadata.st_mode):
        raise InputValidationError("not_regular_file", "input must be a regular file")
    if metadata.st_size <= 0:
        raise InputValidationError("empty_input", "input file is empty")
    if metadata.st_size > max_input_bytes:
        raise InputValidationError(
            "input_too_large", f"input exceeds the configured {max_input_bytes}-byte limit"
        )
    return _identity(metadata)


def _copy_stream(source: BinaryIO, destination: BinaryIO, max_input_bytes: int) -> tuple[int, str]:
    digest = hashlib.sha256()
    size = 0
    while chunk := source.read(_CHUNK_SIZE):
        size += len(chunk)
        if size > max_input_bytes:
            raise InputValidationError(
                "input_too_large", f"input exceeds the configured {max_input_bytes}-byte limit"
            )
        destination.write(chunk)
        digest.update(chunk)
    return size, digest.hexdigest()


def _copy_source_to_stage(source_path: Path, staged_path: Path, limit: int) -> _StagedCopy:
    try:
        with source_path.open("rb") as source, staged_path.open("xb") as destination:
            opened_identity = _identity(os.fstat(source.fileno()))
            size, digest = _copy_stream(source, destination, limit)
            final_identity = _identity(os.fstat(source.fileno()))
            destination.flush()
            os.fsync(destination.fileno())
    except InputValidationError:
        raise
    except OSError as error:
        raise InputValidationError("input_unreadable", "input file could not be staged") from error
    return _StagedCopy(
        opened_identity=opened_identity,
        final_identity=final_identity,
        size=size,
        sha256=digest,
    )


def _post_copy_identity(source: Path) -> _FileIdentity:
    try:
        metadata = source.lstat()
    except OSError as error:
        raise InputValidationError(
            "source_replaced", "source changed or disappeared while it was staged"
        ) from error
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):
        raise InputValidationError("source_replaced", "source was replaced while it was staged")
    return _identity(metadata)


def _read_signature(path: Path) -> bytes:
    try:
        with path.open("rb") as source:
            return source.read(8)
    except OSError as error:
        raise InputValidationError("input_unreadable", "staged input could not be read") from error


def _validate_signature(path: Path, kind: InputKind) -> None:
    signature = _read_signature(path)
    valid = signature.startswith(b"%PDF-") if kind is InputKind.PDF else signature.startswith(b"PK")
    if not valid:
        raise InputValidationError("signature_mismatch", f"content does not match .{kind.value}")


def _member_name_is_safe(name: str) -> bool:
    if not name or "\\" in name or "\x00" in name:
        return False
    path = PurePosixPath(name)
    return not path.is_absolute() and ".." not in path.parts and ":" not in path.parts[0]


def _validate_pptx_container(path: Path) -> None:
    try:
        with ZipFile(path) as archive:
            members = archive.infolist()
            if len(members) > _MAX_ARCHIVE_MEMBERS:
                raise InputValidationError("unsafe_archive", "OOXML archive has too many members")

            total_uncompressed = 0
            names: set[str] = set()
            for member in members:
                if not _member_name_is_safe(member.filename) or member.flag_bits & 0x1:
                    raise InputValidationError(
                        "unsafe_archive", "OOXML archive contains an unsafe or encrypted member"
                    )
                total_uncompressed += member.file_size
                if total_uncompressed > _MAX_ARCHIVE_UNCOMPRESSED_BYTES:
                    raise InputValidationError(
                        "unsafe_archive", "OOXML expanded size exceeds the safety limit"
                    )
                names.add(member.filename)

            required = {"[Content_Types].xml", "ppt/presentation.xml"}
            if not required.issubset(names):
                raise InputValidationError(
                    "invalid_pptx", "OOXML container is missing presentation parts"
                )
            content_types = archive.read("[Content_Types].xml")
            if _PPTX_MAIN_CONTENT_TYPE not in content_types:
                raise InputValidationError(
                    "invalid_pptx", "OOXML container is not a PPTX presentation"
                )
            if archive.testzip() is not None:
                raise InputValidationError("invalid_pptx", "OOXML member checksum failed")
    except InputValidationError:
        raise
    except (BadZipFile, OSError, RuntimeError) as error:
        raise InputValidationError("invalid_pptx", "PPTX container could not be read") from error


@contextmanager
def stage_input(job: IngestionJob) -> Generator[ValidatedInput]:
    """Copy one stable source snapshot to private storage and validate exactly that copy."""
    kind = _kind_for_path(job.source)
    if job.expected_kind is not None and job.expected_kind is not kind:
        raise InputValidationError(
            "kind_mismatch", f"expected {job.expected_kind.value}, received {kind.value}"
        )

    initial_identity = _initial_identity(job.source, job.max_input_bytes)
    with TemporaryDirectory(prefix="impromptu-ingestion-") as temporary_directory:
        directory = Path(temporary_directory)
        directory.chmod(stat.S_IRWXU)
        staged_path = directory / f"input.{kind.value}"
        copied = _copy_source_to_stage(job.source, staged_path, job.max_input_bytes)
        final_path_identity = _post_copy_identity(job.source)
        if not (
            initial_identity
            == copied.opened_identity
            == copied.final_identity
            == final_path_identity
        ):
            raise InputValidationError(
                "source_replaced", "source was modified or replaced while it was staged"
            )
        if copied.size <= 0:
            raise InputValidationError("empty_input", "input file is empty")

        _validate_signature(staged_path, kind)
        if kind is InputKind.PPTX:
            _validate_pptx_container(staged_path)
        staged_path.chmod(stat.S_IRUSR)

        yield ValidatedInput(
            path=staged_path,
            kind=kind,
            size_bytes=copied.size,
            source_sha256=copied.sha256,
            limits=job.limits,
        )

import { createHash } from "node:crypto";
import type { AccountId } from "@impromptu/contracts/private";
import { PrivateDeckContextSchema } from "@impromptu/contracts/private";
import { PublishedDeckArtifactSchema } from "@impromptu/contracts/public";

export function createPreparedDeckArtifacts(
  ownerAccountId: AccountId,
  input: { readonly title: string; readonly content: string },
) {
  const sourceHash = createHash("sha256").update(input.content, "utf8").digest("hex");
  const manifestHash = createHash("sha256")
    .update(`prepared-manifest:${input.title}:${sourceHash}`, "utf8")
    .digest("hex");
  const imageHash = createHash("sha256").update(`public-slide:${sourceHash}`, "utf8").digest("hex");
  const deckVersion = `deck_${sourceHash}`;
  const publicSlideKey = `slide_${sourceHash}`;
  return {
    privateDeck: PrivateDeckContextSchema.parse({
      deckId: `private_deck_${sourceHash}`,
      deckVersion,
      manifestHash,
      title: input.title,
      ownerAccountId,
      aclPolicyVersion: "acl-1",
      privateObjectPrefix: `private-decks/${ownerAccountId}/${sourceHash}`,
      slides: [
        {
          privateSlideId: `private_slide_${sourceHash}`,
          publicSlideKey,
          ordinal: 1,
          speakerNotes: "",
          extractedText: input.content,
          sourceAssetIds: [`asset_${sourceHash}`],
        },
      ],
    }),
    publicDeck: PublishedDeckArtifactSchema.parse({
      deckVersion,
      manifestHash,
      title: input.title,
      slides: [
        {
          publicSlideKey,
          ordinal: 1,
          image: {
            url: `https://public.example.test/slides/${imageHash}.png`,
            contentHash: imageHash,
            width: 1920,
            height: 1080,
          },
          accessibilityLabel: input.title,
        },
      ],
    }),
    sourceHash,
  };
