"""Command-line surface for the server/local-admin ingestion worker."""

import argparse
import json
import os
import stat
import sys
from collections.abc import Sequence
from pathlib import Path
from tempfile import mkstemp
from typing import cast

from pydantic import ValidationError

from impromptu_ingestion.adapters import StructuralExtractionError
from impromptu_ingestion.contracts import CompletedIngestion, IngestionJob
from impromptu_ingestion.doctor import doctor_report
from impromptu_ingestion.validation import InputValidationError
from impromptu_ingestion.worker import ingest


class CliOperationError(RuntimeError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="impromptu-ingestion",
        description="Structural PPTX/PDF ingestion for a server/local-admin worker.",
    )
    commands = parser.add_subparsers(dest="command", required=True)

    doctor = commands.add_parser("doctor", help="report extractor readiness and boundaries")
    doctor.add_argument("--json", action="store_true", help="emit a machine-readable report")

    ingest_command = commands.add_parser("ingest", help="validate and structurally extract a deck")
    ingest_command.add_argument("source", help="local .pptx or .pdf input")
    ingest_command.add_argument(
        "--job-id", default="local_ingest", help="safe worker job identifier"
    )
    ingest_command.add_argument(
        "--output",
        required=True,
        help="new JSON output path; existing files are never overwritten",
    )
    return parser


def _json_bytes(value: object) -> bytes:
    return (
        json.dumps(
            value,
            allow_nan=False,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
        + b"\n"
    )


def _absolute_without_resolving(path: Path) -> Path:
    return path if path.is_absolute() else Path.cwd() / path


def _write_and_sync(descriptor: int, payload: bytes) -> None:
    remaining = memoryview(payload)
    while remaining:
        written = os.write(descriptor, remaining)
        if written <= 0:
            raise OSError("output write made no progress")
        remaining = remaining[written:]
    os.fsync(descriptor)


def _same_file(left: os.stat_result, right: os.stat_result) -> bool:
    return left.st_dev == right.st_dev and left.st_ino == right.st_ino


def _verify_temporary_identity(descriptor: int, temporary: Path) -> os.stat_result:
    descriptor_status = os.fstat(descriptor)
    try:
        path_status = temporary.lstat()
    except OSError as error:
        raise CliOperationError(
            "output_tampered", "output temporary path disappeared before publication"
        ) from error

    if (
        not stat.S_ISREG(descriptor_status.st_mode)
        or not stat.S_ISREG(path_status.st_mode)
        or not _same_file(descriptor_status, path_status)
        or descriptor_status.st_nlink != 1
        or path_status.st_nlink != 1
    ):
        raise CliOperationError(
            "output_tampered", "output temporary path identity or link count changed"
        )
    return descriptor_status


def _verify_published_identity(
    descriptor: int, output: Path, expected_links: int
) -> os.stat_result:
    descriptor_status = os.fstat(descriptor)
    try:
        output_status = output.lstat()
    except OSError as error:
        raise CliOperationError("output_tampered", "published output path disappeared") from error
    if (
        not stat.S_ISREG(output_status.st_mode)
        or not _same_file(descriptor_status, output_status)
        or descriptor_status.st_nlink != expected_links
        or output_status.st_nlink != expected_links
    ):
        raise CliOperationError(
            "output_tampered", "published output identity or link count changed"
        )
    return descriptor_status


def _unlink_if_same_file(path: Path, identity: os.stat_result) -> None:
    try:
        current = path.lstat()
    except FileNotFoundError:
        return
    if stat.S_ISREG(current.st_mode) and _same_file(current, identity):
        path.unlink()


def _publish_no_replace(descriptor: int, temporary: Path, output: Path) -> os.stat_result:
    identity = _verify_temporary_identity(descriptor, temporary)
    try:
        os.link(temporary, output, follow_symlinks=False)
    except FileExistsError as error:
        raise CliOperationError("output_exists", "refusing to overwrite existing output") from error
    except OSError as error:
        raise CliOperationError(
            "output_unwritable", "output file could not be atomically published"
        ) from error

    try:
        return _verify_published_identity(descriptor, output, expected_links=2)
    except BaseException:
        _unlink_if_same_file(output, identity)
        raise


def _verify_completed_output(output: Path, identity: os.stat_result) -> None:
    try:
        output_status = output.lstat()
    except OSError as error:
        raise CliOperationError("output_tampered", "completed output path disappeared") from error
    if (
        not stat.S_ISREG(output_status.st_mode)
        or not _same_file(identity, output_status)
        or output_status.st_nlink != 1
    ):
        raise CliOperationError(
            "output_tampered", "completed output identity or link count changed"
        )


def _write_new_output(path: Path, result: CompletedIngestion) -> None:
    output = _absolute_without_resolving(path)
    try:
        descriptor, temporary_name = mkstemp(
            dir=output.parent,
            prefix=f".{output.name}.",
            suffix=".tmp",
        )
    except OSError as error:
        raise CliOperationError(
            "output_unwritable", "output temporary file could not be created"
        ) from error

    temporary = Path(temporary_name)
    published_identity: os.stat_result | None = None
    try:
        try:
            _write_and_sync(descriptor, _json_bytes(result.model_dump(mode="json")))
            published_identity = _publish_no_replace(descriptor, temporary, output)
        except CliOperationError:
            raise
        except OSError as error:
            raise CliOperationError(
                "output_unwritable", "output file could not be completed"
            ) from error
    finally:
        try:
            os.close(descriptor)
        finally:
            temporary.unlink(missing_ok=True)

    _verify_completed_output(output, published_identity)


def _run_doctor(as_json: bool) -> int:
    report = doctor_report()
    if as_json:
        print(_json_bytes(report.model_dump(mode="json")).decode("utf-8"), end="")
    else:
        state = "ready" if report.ok else "not ready"
        print(f"ingestion worker: {state}")
        print("rendering: not configured (structural extraction only)")
        print("AI/OCR/VLM: disabled")
    return 0 if report.ok else 1


def _run_ingest(source_argument: str, job_id: str, output_argument: str) -> int:
    source = _absolute_without_resolving(Path(source_argument))
    result = ingest(IngestionJob(job_id=job_id, source=source))
    _write_new_output(Path(output_argument), result)
    print(f"completed {result.job_id}: {result.manifest_hash}")
    return 0


def main(argv: Sequence[str] | None = None) -> int:
    """Run the CLI and return a process exit code."""
    arguments = _parser().parse_args(argv)
    command = cast(str, arguments.command)
    try:
        if command == "doctor":
            return _run_doctor(cast(bool, arguments.json))
        return _run_ingest(
            cast(str, arguments.source),
            cast(str, arguments.job_id),
            cast(str, arguments.output),
        )
    except (InputValidationError, StructuralExtractionError, CliOperationError) as error:
        print(f"error[{error.code}]: {error}", file=sys.stderr)
        return 2
    except ValidationError as error:
        print(f"error[invalid_job]: {error}", file=sys.stderr)
        return 2

import { z } from "zod";
import { Sha256Schema, VersionIdSchema } from "./common.ts";
import {
  AccountIdSchema,
  PrivateAssetIdSchema,
  PrivateDeckIdSchema,
  PrivateSlideIdSchema,
} from "./private-identifiers.ts";
import { DeckVersionIdSchema, PublicSlideKeySchema } from "./public-identifiers.ts";

export const PrivateSlideContextSchema = z
  .object({
    privateSlideId: PrivateSlideIdSchema,
    publicSlideKey: PublicSlideKeySchema.nullable(),
    ordinal: z.number().int().positive(),
    speakerNotes: z.string(),
    extractedText: z.string(),
    sourceAssetIds: z.array(PrivateAssetIdSchema),
  })
  .strict();

export const PrivateDeckContextSchema = z
  .object({
    deckId: PrivateDeckIdSchema,
    deckVersion: DeckVersionIdSchema,
    manifestHash: Sha256Schema,
    title: z.string().min(1).max(500),
    ownerAccountId: AccountIdSchema,
    aclPolicyVersion: VersionIdSchema,
    privateObjectPrefix: z.string().min(1),
    slides: z.array(PrivateSlideContextSchema).min(1),
  })
  .strict();

export type PrivateDeckContext = z.infer<typeof PrivateDeckContextSchema>;

import { z } from "zod";
import { Sha256Schema } from "./common.ts";
import { DeckVersionIdSchema, PublicSlideKeySchema } from "./public-identifiers.ts";

export const PublishedSlideImageSchema = z
  .object({
    url: z.url(),
    contentHash: Sha256Schema,
    width: z.number().int().positive(),
    height: z.number().int().positive(),
  })
  .strict();

export const PublishedSlideSchema = z
  .object({
    publicSlideKey: PublicSlideKeySchema,
    ordinal: z.number().int().positive(),
    image: PublishedSlideImageSchema,
    accessibilityLabel: z.string().min(1).max(1_000),
  })
  .strict();

export const PublishedDeckArtifactSchema = z
  .object({
    deckVersion: DeckVersionIdSchema,
    manifestHash: Sha256Schema,
    title: z.string().min(1).max(500),
    slides: z.array(PublishedSlideSchema).min(1),
  })
  .strict();

export type PublishedDeckArtifact = z.infer<typeof PublishedDeckArtifactSchema>;

import { z } from "zod";
import { PublicSlideOccurrenceSchema, Sha256Schema, VersionIdSchema } from "./common.ts";
import {
  CandidateIdSchema,
  SourceIdSchema,
  TranscriptFinalIdSchema,
} from "./private-identifiers.ts";
import { DeckVersionIdSchema, DisplayBindingEpochSchema } from "./public-identifiers.ts";
import {
  PresentationSessionEpochSchema,
  PresentationSessionIdSchema,
} from "./session-identifiers.ts";

export const SourceRevisionSchema = z
  .object({
    sourceId: SourceIdSchema,
    revision: VersionIdSchema,
    contentHash: Sha256Schema,
  })
  .strict();

export const DecisionVersionsSchema = z
  .object({
    acl: VersionIdSchema,
    publicationPolicy: VersionIdSchema,
    rights: VersionIdSchema,
    dlp: VersionIdSchema,
  })
  .strict();

export const CausalEnvelopeSchema = z
  .object({
    presentationSessionId: PresentationSessionIdSchema,
    presentationSessionEpoch: PresentationSessionEpochSchema,
    displayBindingEpoch: DisplayBindingEpochSchema,
    deckVersion: DeckVersionIdSchema,
    manifestHash: Sha256Schema,
    occurrence: PublicSlideOccurrenceSchema,
    transcriptFinalId: TranscriptFinalIdSchema.nullable(),
    source: SourceRevisionSchema,
    decisions: DecisionVersionsSchema,
  })
  .strict();

export const EvidenceCandidateSchema = z
  .object({
    candidateId: CandidateIdSchema,
    candidateVersion: VersionIdSchema,
    provenance: z.enum(["CURATED_PREAPPROVED", "LIVE_VERIFIED"]),
    verdict: z.literal("SUPPORTED"),
    claimText: z.string().min(1),
    evidenceExcerpt: z.string().min(1),
    privateSourceUri: z.string().min(1),
    causal: CausalEnvelopeSchema,
  })
  .strict()
  .superRefine((candidate, context) => {
    if (candidate.provenance === "LIVE_VERIFIED" && candidate.causal.transcriptFinalId === null) {
      context.addIssue({
        code: "custom",
        message: "live verified evidence requires a final transcript identity",
        path: ["causal", "transcriptFinalId"],
      });
    }
  });

export type CausalEnvelope = z.infer<typeof CausalEnvelopeSchema>;
export type EvidenceCandidate = z.infer<typeof EvidenceCandidateSchema>;

import { z } from "zod";
import {
  PublicSlideOccurrenceSchema,
  Sha256Schema,
  TimestampMsSchema,
  VersionIdSchema,
} from "./common.ts";
import {
  DeckVersionIdSchema,
  DisplayBindingEpochSchema,
  ProjectionIdSchema,
  PublicCardRevisionSchema,
} from "./public-identifiers.ts";
import { PresentationSessionEpochSchema } from "./session-identifiers.ts";

export const PublishedAudienceCardSchema = z
  .object({
    projectionId: ProjectionIdSchema,
    status: z.literal("PUBLISHED"),
    mode: z.enum(["CURATED", "LIVE"]).optional(),
    leaseExpiresAtMs: TimestampMsSchema.nullable().optional(),
    publicationPolicyVersion: VersionIdSchema.optional(),
    cardVersion: VersionIdSchema.optional(),
    liveBinding: z
      .object({
        presentationSessionEpoch: PresentationSessionEpochSchema,
        displayBindingEpoch: DisplayBindingEpochSchema,
        publicSlideOccurrence: PublicSlideOccurrenceSchema,
        publicationPolicyVersion: VersionIdSchema,
        cardVersion: VersionIdSchema,
      })
      .strict()
      .optional(),
    claim: z.string().min(1).max(2_000),
    supportSummary: z.string().min(1).max(4_000),
    sourceLabel: z.string().min(1).max(500),
    publishedAtMs: TimestampMsSchema,
    expiresAtMs: TimestampMsSchema.nullable(),
    publicCardRevision: PublicCardRevisionSchema,
    deckVersion: DeckVersionIdSchema,
    manifestHash: Sha256Schema,
    occurrence: PublicSlideOccurrenceSchema,
  })
  .strict()
  .superRefine((card, context) => {
    if (card.mode !== "LIVE") {
      if (
        card.liveBinding !== undefined ||
        card.leaseExpiresAtMs !== undefined ||
        card.publicationPolicyVersion !== undefined ||
        card.cardVersion !== undefined
      ) {
        context.addIssue({ code: "custom", message: "curated cards cannot carry a live lease" });
      }
      return;
    }
    if (
      card.liveBinding === undefined ||
      card.leaseExpiresAtMs === undefined ||
      card.leaseExpiresAtMs === null ||
      card.leaseExpiresAtMs <= card.publishedAtMs ||
      card.leaseExpiresAtMs - card.publishedAtMs > 3_000 ||
      card.expiresAtMs !== card.leaseExpiresAtMs ||
      card.publicationPolicyVersion !== card.liveBinding.publicationPolicyVersion ||
      card.cardVersion !== card.liveBinding.cardVersion ||
      card.liveBinding.publicSlideOccurrence.publicSlideKey !== card.occurrence.publicSlideKey ||
      card.liveBinding.publicSlideOccurrence.occurrenceSeq !== card.occurrence.occurrenceSeq
    ) {
      context.addIssue({
        code: "custom",
        message: "live cards require a matching lease and binding",
      });
    }
  });

export const PublicationTombstoneSchema = z
  .object({
    projectionId: ProjectionIdSchema,
    status: z.enum(["RETRACTED", "EXPIRED"]),
    publicCardRevision: PublicCardRevisionSchema,
    occurredAtMs: TimestampMsSchema,
  })
  .strict();

export type PublishedAudienceCard = z.infer<typeof PublishedAudienceCardSchema>;
export type PublicationTombstone = z.infer<typeof PublicationTombstoneSchema>;

